using System;using System.Linq;using System.Collections.Generic;
public class ColorPreset {public string Name;public UsageRamp Ramp;public ColorPreset Copy(){return new ColorPreset{Name=Name,Ramp=Ramp.Copy()};}}
public static class PaletteLibrary {
 public static List<ColorPreset> Save(IEnumerable<ColorPreset> library,string name,UsageRamp ramp,bool overwrite){name=(name??"").Trim();if(name.Length==0||name.Length>24||name.Any(Char.IsControl))throw new ArgumentException("配色名称需1–24个字。");if(UsageRamp.Presets.Contains(name,StringComparer.OrdinalIgnoreCase))throw new ArgumentException("内置配色不能覆盖，请使用新名称。");ramp.Validate();var values=(library??new ColorPreset[0]).Select(p=>p.Copy()).ToList();bool exists=values.Any(p=>String.Equals(p.Name,name,StringComparison.OrdinalIgnoreCase));if(exists&&!overwrite)throw new ArgumentException("同名配色已存在，请更换名称或更新所选配色。");if(overwrite&&!exists)throw new ArgumentException("请选择一个自定义配色进行更新。");values.RemoveAll(p=>String.Equals(p.Name,name,StringComparison.OrdinalIgnoreCase));if(values.Count>=64)throw new ArgumentException("最多保存64个自定义配色。");values.Add(new ColorPreset{Name=name,Ramp=ramp.Copy()});return values;}
 public static List<ColorPreset> Delete(IEnumerable<ColorPreset> library,string name){if(UsageRamp.Presets.Contains(name)||!(library??new ColorPreset[0]).Any(p=>p.Name==name))throw new ArgumentException("请选择一个自定义配色；内置配色不能删除。");return library.Where(p=>p.Name!=name).Select(p=>p.Copy()).ToList();}
}
